css:
/* From Uiverse.io by Galahhad - Tags: form */
.__UIV_SCOPE__ .form-container__sign-app-buttons svg {
  width: 22px;
  height: auto;
}

.__UIV_SCOPE__ .google svg {
  width: 18px;
  height: auto;
}

.__UIV_SCOPE__ .form-container {
  min-width: 350px;
  box-sizing: border-box;
  font-family: sans-serif;
  color: #4b4b4b;
  min-height: 20px;
  padding: 19px;
  margin-bottom: 20px;
  background-color: #f5f5f5;
}

.__UIV_SCOPE__ .form-container:focus-within:not(:focus) {
  box-shadow: 0 0 6px 3px #caedff;
  -webkit-box-shadow: 0 0 6px 3px #caedff;
  outline: 1px solid #97dbff;
}

.__UIV_SCOPE__ .form-container p {
  font-size: 14px;
  font-weight: bold;
  margin-bottom: 14px;
}

.__UIV_SCOPE__ .top-line {
  padding-top: 12px;
}

.__UIV_SCOPE__ .form-container__form {
  display: flex;
  flex-direction: column;
  row-gap: 16px;
}

.__UIV_SCOPE__ .form-container__form input {
  height: 31px;
  border: 1px solid #d9d9d9;
  padding: 4px;
  font-size: 14px;
  line-height: 1.65;
  -webkit-box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.075);
  box-shadow: inset 0 1px 1px rgba(0, 0, 0, 0.075);
  -webkit-transition: border-color ease-in-out .15s, box-shadow ease-in-out .15s;
  -o-transition: border-color ease-in-out .15s, box-shadow ease-in-out .15s;
  transition: border-color ease-in-out .15s, box-shadow ease-in-out .15s;
}

.__UIV_SCOPE__ .form-container__form input:focus {
  border-color: #00a6fd;
  outline: 0;
  box-shadow: none;
}

.__UIV_SCOPE__ .form-container__register-buttons {
  display: flex;
  column-gap: 10px;
}

.__UIV_SCOPE__ .form-container__sign {
  padding: 8px 20px;
  font-size: 14px;
  line-height: 1.65;
  border-radius: 20px;
  width: 110px;
  white-space: nowrap;
  background-color: #00a6fd;
  border: none;
  color: white;
  font-weight: bold;
  cursor: pointer;
}

.__UIV_SCOPE__ .form-container__sign:first-child:active,
.__UIV_SCOPE__ .form-container__sign:first-child:hover {
  background-color: #0099e9;
}

.__UIV_SCOPE__ .form-container__sign:focus {
  outline-offset: -2px;
  outline: none;
  -webkit-box-shadow: inset 0 0 3px 1px #97dbff;
  box-shadow: inset 0 0 3px 1px #97dbff;
}

.__UIV_SCOPE__ .forgot {
  width: auto;
  padding: 8px 0;
  background: none;
  font-weight: 400;
  color: #428bca;
  text-decoration: none;
}

.__UIV_SCOPE__ .forgot:hover {
  text-decoration: underline;
  color: #4c9dd0;
}

.__UIV_SCOPE__ .form-container__header {
  padding-bottom: 16px;
}

.__UIV_SCOPE__ .form-container__footer {
  padding-top: 12px;
  border-top: 1px solid #cacaca;
}

.__UIV_SCOPE__ .form-container__sign-app-buttons {
  display: flex;
  column-gap: 24px;
}

.__UIV_SCOPE__ .form-container__sign-app-buttons button:not(:first-child) {
  border: none;
  background: none;
  cursor: pointer;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .form-container__sign-app-buttons button:not(:first-child)::before {
  position: absolute;
  content: '';
  width: 120%;
  height: 2px;
  background: rgb(187, 187, 187);
  bottom: 0;
  opacity: 0;
}

.__UIV_SCOPE__ .form-container__sign-app-buttons button:not(:first-child):hover::before {
  opacity: 1;
  transition: 1s;
}

.__UIV_SCOPE__ .form-container__sign-app-buttons button:not(:first-child):focus::before {
  opacity: 1;
  background-color: #4b4b4b;
}

.__UIV_SCOPE__ .form-container__sign-app-buttons button:first-child {
  justify-content: center;
  min-width: 110px;
  height: 40px;
  border: none;
  background: white;
  border-radius: 2px;
  box-shadow: 0 0 1px rgba(0, 0, 0, 0.1), 0 1px 1px #b7b7b7;
  display: flex;
  align-items: center;
  color: #4b4b4b;
  font-size: 13px;
  column-gap: 15px;
  cursor: pointer;
}

.__UIV_SCOPE__ .form-container__sign-app-buttons button:first-child:active {
  background: #eeeeee;
}

.__UIV_SCOPE__ .form-container__sign-app-buttons button:first-child:focus:not(:active) {
  outline: none;
  -webkit-box-shadow: inset 0 0 3px 1px #97dbff;
  box-shadow: inset 0 0 3px 1px #97dbff;
}
